import sqlite3
from langchain_core.tools import tool


@tool
def move_contacts_between_lists(db_path: str, source_list_id: int, target_list_id: int, emails: list) -> dict:
    if not emails:
        return {"error": "emails must not be empty"}
    if source_list_id == target_list_id:
        return {"error": "source and target lists must differ"}
    if not isinstance(emails, list) or not all(isinstance(e, str) and "@" in e for e in emails):
        return {"error": "emails must be a list of valid addresses"}

    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        for lid in (source_list_id, target_list_id):
            row = cur.execute("SELECT id FROM lists WHERE id = ?", (lid,)).fetchone()
            if row is None:
                return {"error": f"list {lid} not found"}

        marks = ",".join("?" for _ in emails)
        found = cur.execute(
            f"SELECT contact_id, email FROM list_members WHERE list_id = ? AND email IN ({marks})",
            [source_list_id, *[e.lower() for e in emails]],
        ).fetchall()
        if not found:
            return {"error": "no matching contacts in source list", "moved": []}

        moved = []
        for contact_id, email in found:
            exists = cur.execute(
                "SELECT 1 FROM list_members WHERE list_id = ? AND contact_id = ?",
                (target_list_id, contact_id),
            ).fetchone()
            if exists:
                cur.execute(
                    "DELETE FROM list_members WHERE list_id = ? AND contact_id = ?",
                    (source_list_id, contact_id),
                )
            else:
                cur.execute(
                    "UPDATE list_members SET list_id = ? WHERE list_id = ? AND contact_id = ?",
                    (target_list_id, source_list_id, contact_id),
                )
            moved.append(email)
        conn.commit()
        return {"moved": moved, "count": len(moved)}
    finally:
        conn.close()

import sqlite3
from agents import function_tool

DB_PATH = "campaigns.db"


@function_tool
def update_campaign_subject(campaign_id: int, subject: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT subject, status FROM campaigns WHERE id = ?", (campaign_id,)).fetchone()
    if row is None or row[1] != "draft":
        conn.close()
        return {"updated": False, "reason": "campaign missing or not a draft"}
    conn.execute("UPDATE campaigns SET subject = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?", (subject.strip(), campaign_id))
    conn.commit()
    conn.close()
    return {"updated": True, "previous": row[0], "new": subject.strip()}

import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("email-marketing")


@mcp.tool()
def tag_inactive_subscribers(days: int, list_id: int) -> dict:
    if days < 1:
        return {"error": "days must be at least 1"}
    db = sqlite3.connect("marketing.db")
    c = db.cursor()
    q = (
        "SELECT s.id, s.email FROM subscribers s "
        "JOIN list_members m ON m.contact_id = s.id "
        "WHERE m.list_id = ? AND s.status = 'active' "
        "AND COALESCE(s.last_open_at, s.created_at) < datetime('now', ?)"
    )
    rows = c.execute(q, (list_id, f"-{days} days")).fetchall()
    n = 0
    for sid, _ in rows:
        r = c.execute(
            "INSERT OR IGNORE INTO subscriber_tags (subscriber_id, tag) VALUES (?, 'inactive')",
            (sid,),
        )
        n += r.rowcount
    db.commit()
    db.close()
    return {"tagged": n, "sample": [e for _, e in rows[:10]]}

import os
import requests
from langchain_core.tools import tool


def _build_payload(name, count):
    return {"text": f"Campaign '{name}' was sent to {count:,} recipients."}


@tool
def send_campaign_webhook_notice(campaign_name: str, recipient_count: int) -> str:
    url = os.environ["SLACK_WEBHOOK_URL"]
    resp = requests.post(url, json=_build_payload(campaign_name, recipient_count), timeout=10)
    resp.raise_for_status()
    return f"Notice posted ({resp.status_code})"
